import argparse
import json
import logging
import re
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import parse_qs, urlsplit

from server.codec import SyncError
from server.store import Store


def _reject_constant(name):
    raise ValueError(f"nonfinite JSON number: {name}")


def parse_json(raw):
    try:
        return json.loads(raw.decode("utf-8"), parse_constant=_reject_constant)
    except (ValueError, UnicodeDecodeError, RecursionError) as exc:
        raise SyncError(400, "invalid") from exc


def parse_limit(value):
    if not isinstance(value, str) or not re.fullmatch(r"[1-9][0-9]{0,2}", value):
        raise SyncError(400, "invalid")
    return int(value)


class Handler(BaseHTTPRequestHandler):
    def read_body(self):
        try:
            length = int(self.headers["Content-Length"])
        except (TypeError, ValueError) as exc:
            raise SyncError(400, "invalid") from exc
        if length < 0:
            raise SyncError(400, "invalid")
        return parse_json(self.rfile.read(length))

    def dispatch(self):
        try:
            route = urlsplit(self.path)
            try:
                query = parse_qs(route.query, keep_blank_values=True, strict_parsing=False,
                                 encoding="utf-8", errors="strict")
            except UnicodeDecodeError as exc:
                raise SyncError(400, "invalid") from exc
            if any(len(values) != 1 for values in query.values()):
                raise SyncError(400, "invalid")
            args = {key: values[0] for key, values in query.items()}
            store = self.server.store
            if self.command == "GET" and route.path == "/health":
                result = {"ok": True}
            elif self.command == "POST" and route.path == "/mutate":
                result = store.mutate(self.read_body())
            elif self.command == "POST" and route.path == "/batch":
                result = store.mutate_batch(self.read_body())
            elif self.command == "GET" and route.path in ("/snapshot", "/pull"):
                if "tenant" not in args or "limit" not in args:
                    raise SyncError(400, "invalid")
                tenant, limit = args["tenant"], parse_limit(args["limit"])
                if route.path == "/snapshot":
                    result = store.snapshot(tenant, limit, args.get("cursor"))
                else:
                    if "checkpoint" not in args:
                        raise SyncError(400, "invalid")
                    result = store.pull(tenant, args["checkpoint"], limit, args.get("cursor"))
            else:
                raise SyncError(404, "not_found")
            status = 200
        except SyncError as exc:
            status, result = exc.status, {"ok": False, "code": exc.code, "detail": exc.detail}
        except Exception:
            logging.exception("Unhandled synchronization request failure")
            status, result = 500, {"ok": False, "code": "internal"}
        payload = json.dumps(result, ensure_ascii=False, allow_nan=False).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(payload)))
        self.end_headers()
        self.wfile.write(payload)

    do_GET = dispatch
    do_POST = dispatch


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--db", required=True)
    parser.add_argument("--port", type=int, default=8080)
    args = parser.parse_args()
    server = ThreadingHTTPServer(("127.0.0.1", args.port), Handler)
    server.database = args.db
    server.store = Store(args.db)
    server.serve_forever()


if __name__ == "__main__":
    main()
